/**
 * Order Integration Tests
 * Generated by BackendForge
 */
const request = require('supertest');
const app = require('../src/app');

describe('Order API', () => {
  let customerToken;
  let adminToken;

  beforeAll(async () => {
    // Register a customer
    const custRes = await request(app).post('/api/auth/register').send({
      name: 'Order Test Customer', email: `order-cust-${Date.now()}@test.com`, password: 'Test@12345',
    });
    customerToken = custRes.body.data?.accessToken;
  });

  describe('POST /api/orders/:id/cancel', () => {
    it('should reject unauthenticated cancel requests', async () => {
      const res = await request(app)
        .post('/api/orders/fake-id/cancel')
        .send({ reason: 'Changed my mind' });
      expect(res.statusCode).toBe(401);
    });

    it('should return 404 for non-existent order', async () => {
      if (!customerToken) return;
      const res = await request(app)
        .post('/api/orders/00000000-0000-0000-0000-000000000000/cancel')
        .set('Authorization', `Bearer ${customerToken}`)
        .send({ reason: 'Test cancel' });
      expect(res.statusCode).toBe(404);
    });
  });

  describe('GET /api/users/orders', () => {
    it('should return empty order history for new user', async () => {
      if (!customerToken) return;
      const res = await request(app)
        .get('/api/users/orders')
        .set('Authorization', `Bearer ${customerToken}`);
      expect(res.statusCode).toBe(200);
      expect(res.body.success).toBe(true);
      expect(Array.isArray(res.body.data)).toBe(true);
    });
  });
});
